  "tasks": [
    {
      "task_id": "T1",
      "title": "按城市统计利润总额",
      "business_question": "各城市的利润总额是多少？（注：数据集中无“利润”字段，仅有“销售额”，此处以“销售额”作为代理指标进行汇总）",
      "priority": "P0",
      "priority_reason": "核心需求C01和C02要求比较各城市利润总额。由于缺少直接的利润数值字段，必须明确此限制并基于现有最接近的财务指标（销售额）或标记缺失能力来回答。若强行计算则违反不发明字段原则；若忽略则无法回答。根据规则，核心需求需保留为P0，若数据不支持需记录missing_inputs。但通常业务中若无利润字段，可能用户意指销售额或数据缺失。鉴于严格遵循“不发明字段”，且“利润总额”在profile.fields中不存在对应ID，此任务应标记为不可直接执行的核心缺口，或者如果假设用户混淆了概念，需澄清。根据指令“如果核心请求缺少字段，保留 P0 任务，missing_inputs 写出缺少的数据... steps 可为 []”。因此，这里判定为缺少‘利润’字段。",
      "requirement_ids": [
        "C01",
        "C02"
      ],
      "depends_on": [],
      "missing_inputs": [
        "数据集中缺少名为'利润'或'利润总额'的数值字段，无法直接计算利润总额。当前可用数值字段仅为'销售额'(field_0005)。"
      ],
      "steps": []
    }
  ]
}
